            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"140\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"200\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">THE COGNITIVE MODEL</text><text x=\"550\" y=\"245\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">What sits between the event and the feeling?</text><text x=\"550\" y=\"285\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">Think about Jordan and the cancelled dinner</text><rect x=\"100\" y=\"420\" width=\"260\" height=\"120\" rx=\"20\" fill=\"rgba(59,130,246,0.15)\" stroke=\"#3b82f6\" stroke-width=\"2\"/><text x=\"230\" y=\"490\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">A: Event</text><rect x=\"420\" y=\"420\" width=\"260\" height=\"120\" rx=\"20\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"490\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">B: ?</text><rect x=\"740\" y=\"420\" width=\"260\" height=\"120\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"870\" y=\"490\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"24\">C: Feeling</text></svg>",
