            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">WISDOM</text><rect x=\"100\" y=\"250\" width=\"900\" height=\"300\" rx=\"20\" fill=\"rgba(139,92,246,0.1)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"340\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"26\">\"Worry does not empty tomorrow</text><text x=\"550\" y=\"385\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"26\">of its sorrow. It empties today</text><text x=\"550\" y=\"430\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"26\">of its strength.\"</text><text x=\"900\" y=\"505\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"20\">-- Attributed to Corrie ten Boom</text><text x=\"550\" y=\"660\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Worry time gives today its strength back</text></svg>",
