            "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">KNOWLEDGE CHECK</text><rect x=\"150\" y=\"120\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.1)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"180\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"22\">MATCH THERAPY TO PROBLEM</text><text x=\"550\" y=\"225\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"18\">Some problems need targeted methods</text><text x=\"550\" y=\"260\" text-anchor=\"middle\" fill=\"#888\" font-size=\"16\">PTSD, OCD, phobias especially</text><rect x=\"150\" y=\"360\" width=\"360\" height=\"140\" rx=\"20\" fill=\"rgba(236,72,153,0.1)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"330\" y=\"440\" text-anchor=\"middle\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"24\">PTSD</text><path d=\"M510 430 L580 430\" stroke=\"#14b8a6\" stroke-width=\"2\"/><polygon points=\"590,430 578,422 578,438\" fill=\"#14b8a6\"/><rect x=\"590\" y=\"360\" width=\"360\" height=\"140\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"770\" y=\"440\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">?</text></svg>",
